/**
 * Milestone rules that do not need the database: the state conflict error the
 * service layer throws, the name key that makes names unique, and the overdue
 * test.
 */
import type { IsoTimestamp } from "@/types/common";

export type MilestoneStateReason =
  | "closed"
  | "already_open"
  | "too_many_open"
  | "name_taken";

/** A milestone change the current state refuses; mapped to `conflict`. */
export class MilestoneStateError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly reason: MilestoneStateReason) {
    super(`Milestone state conflict: ${reason}`);
    this.name = "MilestoneStateError";
  }
}

/**
 * Names are unique per project without regard to letter case or surrounding
 * spaces, so the stored key is the trimmed, lower-cased name.
 */
export function milestoneNameKey(name: string): string {
  return name.trim().toLowerCase();
}

/** Open, dated in the past, and still holding open issues. */
export function isMilestoneOverdue(
  milestone: { readonly closedAt: IsoTimestamp | null; readonly targetDate: IsoTimestamp | null },
  openIssues: number,
  now: Date = new Date(),
): boolean {
  if (milestone.closedAt !== null) return false;
  if (milestone.targetDate === null) return false;
  if (openIssues <= 0) return false;
  return Date.parse(milestone.targetDate) < now.getTime();
}
