  const milestone = await milestoneRepo.insertMilestone({
    orgId: input.orgId,
    projectId: project.id,
    name: input.name.trim(),
    nameKey: milestoneNameKey(input.name),
    targetDate: input.targetDate,
  });

  await emit("milestone.created", {
    ...actorEnvelope(actor),
    milestoneId: milestone.id,
    projectId: milestone.projectId,
  });

  return milestone;
}

/** Renames and retargets; the rename is checked against every milestone of the project. */
export async function updateMilestone(
  actor: Actor,
  input: UpdateMilestoneInput,
): Promise<Milestone> {
  const { milestone } = await loadWritableMilestone(
    actor,
    input.orgId,
    input.milestoneId,
  );

  const name = input.name?.trim();
  if (name !== undefined) {
    await assertNameFree(input.orgId, milestone.projectId, name, milestone.id);
  }

  return milestoneRepo.updateMilestone(input.orgId, milestone.id, {
    ...(name === undefined
      ? {}
      : { name, nameKey: milestoneNameKey(name) }),
    ...(input.targetDate === undefined
      ? {}
      : { targetDate: input.targetDate }),
  });
}

/**
 * Closes a milestone. Its open live issues move to `moveOpenIssuesTo` (another
 * open milestone of the same project) or out of any milestone. Every check
 * runs before the first write, so a refused close changes nothing.
 */
export async function closeMilestone(
  actor: Actor,
  input: CloseMilestoneInput,
): Promise<{ milestone: Milestone; movedIssueIds: readonly IssueId[] }> {
  const { milestone } = await loadWritableMilestone(
    actor,
    input.orgId,
    input.milestoneId,
  );
  if (milestone.closedAt !== null) {
    throw new MilestoneStateError("closed");
  }

  const target = await resolveCloseTarget(actor, milestone, input);

  const openIssues = await issueRepo.listOpenIssuesInMilestone(
    input.orgId,
    milestone.id,
  );
  const movedIssueIds = openIssues.map((issue) => issue.id);
  const movedToMilestoneId = target?.id ?? null;

  await issueRepo.moveIssuesToMilestone(
    input.orgId,
    movedIssueIds,
    movedToMilestoneId,
  );
  const closed = await milestoneRepo.setMilestoneClosedAt(
    input.orgId,
    milestone.id,
    toIsoTimestamp(new Date()),
  );

  await emit("milestone.closed", {
    ...actorEnvelope(actor),
    milestoneId: closed.id,
    projectId: closed.projectId,
    movedToMilestoneId,
    movedIssueIds,
  });

  return { milestone: closed, movedIssueIds };
}

/** Validates the close target; `null` means "take the issues out of any milestone". */
async function resolveCloseTarget(
  actor: Actor,
  milestone: Milestone,
  input: CloseMilestoneInput,
): Promise<Milestone | null> {
  const targetId = input.moveOpenIssuesTo;
  if (targetId === null) return null;

  if (targetId === milestone.id) {
    throw new NotFoundError("Milestone", targetId);
  }
  const target = requireFound(
    await milestoneRepo.findMilestoneById(actor.orgId, targetId),
    "Milestone",
    targetId,
  );
  if (target.projectId !== milestone.projectId) {
    throw new NotFoundError("Milestone", targetId);
  }
  if (target.closedAt !== null) {
    throw new MilestoneStateError("closed");
  }
  return target;
}

export async function reopenMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<Milestone> {
  const { milestone } = await loadWritableMilestone(actor, orgId, milestoneId);
  if (milestone.closedAt === null) {
    throw new MilestoneStateError("already_open");
  }
  await assertRoomForOpen(orgId, milestone.projectId);

  const reopened = await milestoneRepo.setMilestoneClosedAt(
    orgId,
    milestone.id,
    null,
  );

  await emit("milestone.reopened", {
    ...actorEnvelope(actor),
    milestoneId: reopened.id,
    projectId: reopened.projectId,
  });

  return reopened;
}

export async function listMilestones(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly MilestoneWithProgress[]> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const all = await milestoneRepo.listMilestonesForProject(orgId, projectId);
  return withProgress(orgId, [...all].sort(compareMilestones));
}

export async function getMilestone(
  actor: Actor,
  orgId: OrgId,
  milestoneId: MilestoneId,
): Promise<MilestoneWithProgress> {
  assertOrgScope(actor, orgId);

  const milestone = requireFound(
    await milestoneRepo.findMilestoneById(orgId, milestoneId),
    "Milestone",
    milestoneId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(orgId, milestone.projectId),
    "Project",
    milestone.projectId,
  );
  assertCan(actor, "project:read", projectResource(project));

  const [item] = await withProgress(orgId, [milestone]);
  return requireFound(item, "Milestone", milestoneId);
}

/** Attaches progress and the overdue flag, one progress query for the whole list. */
async function withProgress(
  orgId: OrgId,
  list: readonly Milestone[],
): Promise<readonly MilestoneWithProgress[]> {
  const progress = await milestoneRepo.getMilestoneProgress(
    orgId,
    list.map((milestone) => milestone.id),
  );
  const now = new Date();

  return list.map((milestone) => {
    const counts = progress.get(milestone.id) ?? { total: 0, open: 0, closed: 0 };
    return {
      milestone,
      progress: counts,
      overdue: isMilestoneOverdue(milestone, counts.open, now),
    };
  });
}

/**
 * Open milestones before closed ones; within each group the earliest target
 * date first, undated last; ties by creation, oldest first.
 */
function compareMilestones(a: Milestone, b: Milestone): number {
  const aOpen = a.closedAt === null;
  const bOpen = b.closedAt === null;
  if (aOpen !== bOpen) return aOpen ? -1 : 1;

  const byTarget = compareTargetDates(a.targetDate, b.targetDate);
  if (byTarget !== 0) return byTarget;

  return a.createdAt.localeCompare(b.createdAt) || a.id.localeCompare(b.id);
}

function compareTargetDates(
  a: Milestone["targetDate"],
  b: Milestone["targetDate"],
): number {
  if (a === null && b === null) return 0;
  if (a === null) return 1;
  if (b === null) return -1;
  return Date.parse(a) - Date.parse(b);
}
