cat > tests/services/milestone-service.test.ts <<'EOF'
/**
 * Milestone lifecycle through the service layer: naming and the open cap, closing with
 * issue moves and alerts, refusals that must change nothing, progress and ordering.
 */
import { afterAll, beforeAll, beforeEach, describe, expect, it } from "vitest";
import { MAX_OPEN_MILESTONES_PER_PROJECT } from "@/config/constants";
import { MilestoneStateError } from "@/lib/milestones";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { NotFoundError } from "@/server/services/_support";
import * as issueService from "@/server/services/issue-service";
import * as milestoneService from "@/server/services/milestone-service";
import * as notificationService from "@/server/services/notification-service";
import * as projectService from "@/server/services/project-service";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { MilestoneId, OrgId, ProjectId } from "@/types/common";
import type { Issue } from "@/types/issue";

const OTHER_ORG = "01HZZZCCCCCCCCCCCCCCCCCCCC" as OrgId;
const PAST = "2020-01-01T00:00:00.000Z";
const FUTURE = "2099-01-01T00:00:00.000Z";

let cleanup: () => void;
let tenant: Tenant;
let counter = 0;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  void notificationService;
});

afterAll(() => {
  cleanup();
});

beforeEach(async () => {
  counter += 1;
  tenant = await createTenant(`ms${counter}`);
});

function milestoneInput(name: string, targetDate: string | null = null) {
  return {
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    name,
    targetDate,
  } as const;
}

async function makeMilestone(name: string, targetDate: string | null = null) {
  return milestoneService.createMilestone(tenant.actors.admin, milestoneInput(name, targetDate));
}

async function makeIssue(
  overrides: { milestoneId?: MilestoneId | null; status?: Issue["status"]; assigneeId?: Tenant["userIds"]["member"] | null } = {},
): Promise<Issue> {
  return issueService.createIssue(tenant.actors.member, {
    ...issueInput(tenant.org.id, tenant.project.id, {
      title: "Milestone work item",
      assigneeId: overrides.assigneeId ?? null,
    }),
    status: overrides.status ?? "backlog",
    milestoneId: overrides.milestoneId ?? null,
  });
}

async function alertsFor(userId: Tenant["userIds"]["member"]) {
  const page = await notificationRepo.listNotifications({
    orgId: tenant.org.id,
    recipientId: userId,
    unreadOnly: false,
    limit: 100,
    cursor: null,
    kind: ["issue_milestone_changed"],
  });
  return page.items;
}

describe("names and the open cap", () => {
  it("refuses a name already used in the project, ignoring case and surrounding spaces", async () => {
    await makeMilestone("Beta");

    await expect(makeMilestone("  beta ")).rejects.toMatchObject({
      reason: "name_taken",
    });
  });

  it("allows the same name in another project of the same workspace", async () => {
    await makeMilestone("Shared");
    const other = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Other project",
      slug: "other",
      key: "OTH",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    const milestone = await milestoneService.createMilestone(tenant.actors.admin, {
      ...milestoneInput("Shared"),
      projectId: other.id,
    });
    expect(milestone.projectId).toBe(other.id);
  });

  it("refuses the open milestone beyond the cap, and frees a slot when one closes", async () => {
    const created = [];
    for (let i = 0; i < MAX_OPEN_MILESTONES_PER_PROJECT; i += 1) {
      created.push(await makeMilestone(`M${i}`));
    }

    await expect(makeMilestone("one too many")).rejects.toMatchObject({
      reason: "too_many_open",
    });

    await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: created[0].id,
      moveOpenIssuesTo: null,
    });
    await expect(makeMilestone("now fits")).resolves.toBeDefined();
  });

  it("refuses to reopen while the cap is full", async () => {
    const first = await makeMilestone("Closed first");
    await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: first.id,
      moveOpenIssuesTo: null,
    });
    for (let i = 0; i < MAX_OPEN_MILESTONES_PER_PROJECT; i += 1) {
      await makeMilestone(`Fill ${i}`);
    }

    await expect(
      milestoneService.reopenMilestone(tenant.actors.admin, tenant.org.id, first.id),
    ).rejects.toMatchObject({ reason: "too_many_open" });
  });

  it("refuses to reopen an open milestone and to close a closed one", async () => {
    const milestone = await makeMilestone("Once");

    await expect(
      milestoneService.reopenMilestone(tenant.actors.admin, tenant.org.id, milestone.id),
    ).rejects.toBeInstanceOf(MilestoneStateError);

    await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: milestone.id,
      moveOpenIssuesTo: null,
    });
    await expect(
      milestoneService.closeMilestone(tenant.actors.admin, {
        orgId: tenant.org.id,
        milestoneId: milestone.id,
        moveOpenIssuesTo: null,
      }),
    ).rejects.toMatchObject({ reason: "closed" });
  });
});

describe("closing", () => {
  it("moves open issues to the target, leaves closed ones, and alerts each assignee once", async () => {
    const source = await makeMilestone("Source");
    const target = await makeMilestone("Target");
    const openForMember = await makeIssue({
      milestoneId: source.id,
      assigneeId: tenant.userIds.member,
    });
    const openForAdmin = await makeIssue({
      milestoneId: source.id,
      assigneeId: tenant.userIds.admin,
    });
    const doneIssue = await makeIssue({ milestoneId: source.id, status: "done" });

    const result = await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: source.id,
      moveOpenIssuesTo: target.id,
    });

    expect([...result.movedIssueIds].sort()).toEqual(
      [openForMember.id, openForAdmin.id].sort(),
    );
    expect(result.milestone.closedAt).not.toBeNull();
    expect((await issueRepo.findIssueById(tenant.org.id, openForMember.id))?.milestoneId).toBe(target.id);
    expect((await issueRepo.findIssueById(tenant.org.id, doneIssue.id))?.milestoneId).toBe(source.id);

    expect(await alertsFor(tenant.userIds.member)).toHaveLength(1);
    // The admin closed the milestone: they are not alerted about their own closing.
    expect(await alertsFor(tenant.userIds.admin)).toHaveLength(0);
  });

  it("takes open issues out of any milestone when no target is named", async () => {
    const source = await makeMilestone("Loose ends");
    const issue = await makeIssue({ milestoneId: source.id });

    const result = await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: source.id,
      moveOpenIssuesTo: null,
    });

    expect(result.movedIssueIds).toEqual([issue.id]);
    expect((await issueRepo.findIssueById(tenant.org.id, issue.id))?.milestoneId).toBeNull();
  });

  it("refuses a closed target, the milestone itself, or another project's milestone, changing nothing", async () => {
    const source = await makeMilestone("Refused source");
    const closedTarget = await makeMilestone("Closed target");
    await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: closedTarget.id,
      moveOpenIssuesTo: null,
    });
    const issue = await makeIssue({ milestoneId: source.id });

    await expect(
      milestoneService.closeMilestone(tenant.actors.admin, {
        orgId: tenant.org.id,
        milestoneId: source.id,
        moveOpenIssuesTo: closedTarget.id,
      }),
    ).rejects.toMatchObject({ reason: "closed" });
    await expect(
      milestoneService.closeMilestone(tenant.actors.admin, {
        orgId: tenant.org.id,
        milestoneId: source.id,
        moveOpenIssuesTo: source.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const stillThere = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stillThere?.milestoneId).toBe(source.id);
    const milestone = await milestoneService.getMilestone(tenant.actors.admin, tenant.org.id, source.id);
    expect(milestone.milestone.closedAt).toBeNull();
  });
});

describe("issue placement", () => {
  it("refuses to put an issue into a closed milestone, at creation or later", async () => {
    const milestone = await makeMilestone("Done with");
    await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: milestone.id,
      moveOpenIssuesTo: null,
    });

    await expect(makeIssue({ milestoneId: milestone.id })).rejects.toBeInstanceOf(
      MilestoneStateError,
    );

    const issue = await makeIssue();
    await expect(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId: milestone.id,
      }),
    ).rejects.toBeInstanceOf(MilestoneStateError);
  });

  it("moves an issue in and out, returning the stored issue", async () => {
    const milestone = await makeMilestone("Sprint");
    const issue = await makeIssue();

    const moved = await issueService.setIssueMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      milestoneId: milestone.id,
    });
    expect(moved.milestoneId).toBe(milestone.id);

    const cleared = await issueService.setIssueMilestone(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      milestoneId: null,
    });
    expect(cleared.milestoneId).toBeNull();
  });

  it("refuses a milestone from another project as not found", async () => {
    const other = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Elsewhere",
      slug: "elsewhere",
      key: "ELS",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const foreign = await milestoneService.createMilestone(tenant.actors.admin, {
      ...milestoneInput("Foreign"),
      projectId: other.id as ProjectId,
    });
    const issue = await makeIssue();

    await expect(
      issueService.setIssueMilestone(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        milestoneId: foreign.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });
});

describe("reads, progress and ordering", () => {
  it("counts live issues by state and flags overdue only when open issues remain", async () => {
    const late = await makeMilestone("Late", PAST);
    await makeIssue({ milestoneId: late.id });
    await makeIssue({ milestoneId: late.id, status: "done" });

    const detail = await milestoneService.getMilestone(tenant.actors.viewer, tenant.org.id, late.id);
    expect(detail.progress).toEqual({ total: 2, open: 1, closed: 1 });
    expect(detail.overdue).toBe(true);

    const undated = await makeMilestone("No date");
    await makeIssue({ milestoneId: undated.id });
    const noDate = await milestoneService.getMilestone(tenant.actors.viewer, tenant.org.id, undated.id);
    expect(noDate.overdue).toBe(false);
