function milestoneInput(name: string, targetDate: string | null = null) {
  return {
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    name,
    targetDate,
  } as const;
}

async function makeMilestone(name: string, targetDate: string | null = null) {
  return milestoneService.createMilestone(tenant.actors.admin, milestoneInput(name, targetDate));
}

async function makeIssue(
  overrides: { milestoneId?: MilestoneId | null; status?: Issue["status"]; assigneeId?: Tenant["userIds"]["member"] | null } = {},
): Promise<Issue> {
  return issueService.createIssue(tenant.actors.member, {
    ...issueInput(tenant.org.id, tenant.project.id, {
      title: "Milestone work item",
      assigneeId: overrides.assigneeId ?? null,
    }),
    status: overrides.status ?? "backlog",
    milestoneId: overrides.milestoneId ?? null,
  });
}

async function alertsFor(userId: Tenant["userIds"]["member"]) {
  const page = await notificationRepo.listNotifications({
    orgId: tenant.org.id,
    recipientId: userId,
    unreadOnly: false,
    limit: 100,
    cursor: null,
    kind: ["issue_milestone_changed"],
  });
  return page.items;
