describe("names and the open cap", () => {
  it("refuses a name already used in the project, ignoring case and surrounding spaces", async () => {
    await makeMilestone("Beta");

    await expect(makeMilestone("  beta ")).rejects.toMatchObject({
      reason: "name_taken",
    });
  });

  it("allows the same name in another project of the same workspace", async () => {
    await makeMilestone("Shared");
    const other = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Other project",
      slug: "other",
      key: "OTH",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    const milestone = await milestoneService.createMilestone(tenant.actors.admin, {
      ...milestoneInput("Shared"),
      projectId: other.id,
    });
    expect(milestone.projectId).toBe(other.id);
