  it("refuses the open milestone beyond the cap, and frees a slot when one closes", async () => {
    const created = [];
    for (let i = 0; i < MAX_OPEN_MILESTONES_PER_PROJECT; i += 1) {
      created.push(await makeMilestone(`M${i}`));
