    await expect(makeMilestone("one too many")).rejects.toMatchObject({
      reason: "too_many_open",
    });

    await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: created[0].id,
      moveOpenIssuesTo: null,
    });
    await expect(makeMilestone("now fits")).resolves.toBeDefined();
  });

