      milestoneId: source.id,
      assigneeId: tenant.userIds.member,
    });
    const openForAdmin = await makeIssue({
      milestoneId: source.id,
      assigneeId: tenant.userIds.admin,
    });
    const doneIssue = await makeIssue({ milestoneId: source.id, status: "done" });

    const result = await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: source.id,
      moveOpenIssuesTo: target.id,
    });

    expect([...result.movedIssueIds].sort()).toEqual(
      [openForMember.id, openForAdmin.id].sort(),
    );
    expect(result.milestone.closedAt).not.toBeNull();
    expect((await issueRepo.findIssueById(tenant.org.id, openForMember.id))?.milestoneId).toBe(target.id);
    expect((await issueRepo.findIssueById(tenant.org.id, doneIssue.id))?.milestoneId).toBe(source.id);

    expect(await alertsFor(tenant.userIds.member)).toHaveLength(1);
    // The admin closed the milestone: they are not alerted about their own closing.
    expect(await alertsFor(tenant.userIds.admin)).toHaveLength(0);
  });

  it("takes open issues out of any milestone when no target is named", async () => {
    const source = await makeMilestone("Loose ends");
    const issue = await makeIssue({ milestoneId: source.id });

    const result = await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: source.id,
      moveOpenIssuesTo: null,
