    expect(result.movedIssueIds).toEqual([issue.id]);
    expect((await issueRepo.findIssueById(tenant.org.id, issue.id))?.milestoneId).toBeNull();
  });

  it("refuses a closed target, the milestone itself, or another project's milestone, changing nothing", async () => {
    const source = await makeMilestone("Refused source");
    const closedTarget = await makeMilestone("Closed target");
    await milestoneService.closeMilestone(tenant.actors.admin, {
      orgId: tenant.org.id,
      milestoneId: closedTarget.id,
      moveOpenIssuesTo: null,
    });
    const issue = await makeIssue({ milestoneId: source.id });

    await expect(
      milestoneService.closeMilestone(tenant.actors.admin, {
        orgId: tenant.org.id,
        milestoneId: source.id,
        moveOpenIssuesTo: closedTarget.id,
      }),
    ).rejects.toMatchObject({ reason: "closed" });
    await expect(
      milestoneService.closeMilestone(tenant.actors.admin, {
        orgId: tenant.org.id,
        milestoneId: source.id,
        moveOpenIssuesTo: source.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    const stillThere = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stillThere?.milestoneId).toBe(source.id);
    const milestone = await milestoneService.getMilestone(tenant.actors.admin, tenant.org.id, source.id);
    expect(milestone.milestone.closedAt).toBeNull();
  });
});

